-- Simple approach: Just update ticket_number in database
-- Members and treasurers will see the updated numbers immediately
-- QR codes can be regenerated by members when they open their tickets page

-- Update all paid tickets with new format
UPDATE ticket_purchases
SET ticket_number = 'TKT' || LPAD(
  SUBSTRING(REGEXP_REPLACE(id::text, '[^0-9]', '', 'g'), 1, 10),
  10,
  '0'
)
WHERE payment_status = 'paid';

-- Verify the update
SELECT 
  id,
  ticket_number,
  payment_status,
  created_at
FROM ticket_purchases 
WHERE payment_status = 'paid'
ORDER BY created_at DESC
LIMIT 10;

-- This will update ticket numbers like:
-- ID 70546366 -> TKT0070546366
-- ID 7054636640 -> TKT7054636640
